/**
 * Validation rule data, sourced directly from the University of Portsmouth
 * UTM spreadsheet's own lookup tabs — "Term Source", "Default medium - term"
 * and "Campaign name, GA4 medium, cont[ent]" — not reverse-engineered from
 * historical usage. A few small, deliberate corrections were applied on top
 * of the raw tab data; see README "Validation rules" for exactly what and
 * why.
 *
 * Campaign Term names are themselves prefixed "paid-" or "organic-" (e.g.
 * "organic-email", "paid-search") — that prefix carries the Paid/Organic
 * meaning. There is no separate Paid/Organic input anywhere in this tool.
 */

// medium -> [terms], from the "Default medium - term" tab. Corrections
// applied on top of the raw tab (see README):
// - "organic-out-of-home" / "paid-out-of-home" (print/video rows) normalized
//   to "organic-outofhome" / "paid-outofhome", the spelling the "Term
//   Source" tab actually defines sources for.
// - "sponsorship", "uni-frog" and a duplicate "paid-email" dropped from
//   affiliate — data-entry noise (uni-frog is a Source name elsewhere, not
//   a Term; sponsorship has no defined sources and doesn't fit the
//   paid-/organic- naming convention every other Term follows).
// - "paid-3rd-party-email" and "paid-3rd-party-listicle" added to
//   affiliate — both have real Source data in the "Term Source" tab and
//   fit affiliate's other paid-3rd-party-* terms, but were missing from
//   this tab's affiliate row.
export const MEDIUM_TERM_MAP = {
  affiliate: ['paid-3rd-party-website', 'paid-3rd-party-virtual-event', 'paid-digital-publishing', 'paid-news', 'paid-web-forum', 'paid-3rd-party-email', 'paid-3rd-party-listicle'],
  audio: ['organic-audio', 'paid-audio'],
  email: ['organic-email', 'paid-email'],
  organic: ['organic-search'],
  postal: ['organic-directmail', 'paid-directmail'],
  ppc: ['paid-display', 'paid-search', 'paid-social', 'paid-video', 'pmax', 'demand-gen'],
  print: ['organic-outofhome', 'organic-print', 'paid-outofhome', 'paid-print'],
  push: ['organic-push-notification', 'paid-push-notification'],
  referral: ['organic-3rd-party-website', 'organic-digital-publishing', 'organic-news', 'organic-web-forum', 'organic-3rd-party-virtual-event'],
  sms: ['organic-sms', 'paid-sms', 'paid-whatsapp'],
  social: ['organic-social'],
  video: ['organic-video', 'organic-outofhome', 'paid-outofhome'],
};

